class Solution {
public:
    int maxChunksToSorted(vector<int>& arr) {
        int count = 0;
        int maxSoFar = 0;
        for (int i = 0; i < (int)arr.size(); i++) {
            if (arr[i] > maxSoFar) {
                maxSoFar = arr[i];
            }
            if (maxSoFar == i) {
                count++;
            }
        }
        return count;
    }
};
